#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <microhttpd.h>

// ECS Fargate service: User profile lookup microservice
// Handles /api/v2/profile?user_id=<id>&fields=<comma-separated>

typedef struct {
    char *display_name;
    char *email;
    char *department;
    int active;
} UserProfile;

typedef struct {
    char *field_name;
    size_t offset;
} FieldMapping;

static FieldMapping field_map[] = {
    {"display_name", offsetof(UserProfile, display_name)},
    {"email", offsetof(UserProfile, email)},
    {"department", offsetof(UserProfile, department)},
    {NULL, 0}
};

UserProfile* lookup_user(const char *user_id) {
    // Simulates DB lookup - returns NULL for unknown users
    if (user_id == NULL || strlen(user_id) == 0)
        return NULL;
    if (strcmp(user_id, "deleted") == 0)
        return NULL;  // Soft-deleted users return NULL

    UserProfile *profile = calloc(1, sizeof(UserProfile));
    if (!profile) return NULL;

    profile->display_name = strdup("John Doe");
    profile->email = strdup("john@example.com");
    profile->department = NULL;  // Not all users have department set
    profile->active = 1;
    return profile;
}

char* serialize_field(UserProfile *profile, const char *field) {
    for (int i = 0; field_map[i].field_name != NULL; i++) {
        if (strcmp(field, field_map[i].field_name) == 0) {
            char **value_ptr = (char **)((char *)profile + field_map[i].offset);
            // BUG: No NULL check on *value_ptr before strlen/use
            // If department is NULL, this dereferences NULL
            size_t len = strlen(*value_ptr);
            char *result = malloc(len + strlen(field) + 16);
            sprintf(result, "\"%s\":\"%s\"", field, *value_ptr);
            return result;
        }
    }
    return strdup("\"unknown\":\"\"" );
}

char* build_response(const char *user_id, const char *fields) {
    UserProfile *profile = lookup_user(user_id);

    // BUG: No NULL check on profile for deleted/unknown users
    // Requesting profile for user_id="deleted" causes NULL deref

    char *response = malloc(4096);
    strcpy(response, "{");

    char *fields_copy = strdup(fields);
    char *token = strtok(fields_copy, ",");
    int first = 1;

    while (token != NULL) {
        if (!first) strcat(response, ",");
        char *serialized = serialize_field(profile, token);
        strcat(response, serialized);
        free(serialized);
        first = 0;
        token = strtok(NULL, ",");
    }

    strcat(response, "}");
    free(fields_copy);
    return response;
}

static enum MHD_Result handler(void *cls, struct MHD_Connection *connection,
    const char *url, const char *method, const char *version,
    const char *upload_data, size_t *upload_data_size, void **con_cls) {

    if (strcmp(url, "/api/v2/profile") != 0)
        return MHD_NO;

    const char *user_id = MHD_lookup_connection_value(connection,
        MHD_GET_ARGUMENT_KIND, "user_id");
    const char *fields = MHD_lookup_connection_value(connection,
        MHD_GET_ARGUMENT_KIND, "fields");

    if (!fields) fields = "display_name,email";

    char *resp_body = build_response(user_id, fields);
    struct MHD_Response *response = MHD_create_response_from_buffer(
        strlen(resp_body), resp_body, MHD_RESPMEM_MUST_FREE);

    int ret = MHD_queue_response(connection, 200, response);
    MHD_destroy_response(response);
    return ret;
}

int main(void) {
    struct MHD_Daemon *d = MHD_start_daemon(MHD_USE_THREAD_PER_CONNECTION,
        8080, NULL, NULL, &handler, NULL, MHD_OPTION_END);
    if (!d) return 1;
    printf("Profile service listening on :8080\n");
    getchar();
    MHD_stop_daemon(d);
    return 0;
}
